/// Temporary local namespace for Error-context disposition identities.
///
/// The outer UUIDv5 namespace is derived from the current agent DB's
/// conversation identity and the inner name is the canonical disposition
/// label plus message id. Issue #74 replaces only the outer namespace with the
/// final `PersonalityAgentId`; callers never construct or persist a tenant /
/// workspace owner.
const ERROR_CONTEXT_DISPOSITION_NAMESPACE: Uuid = Uuid::from_bytes([
    0x4a, 0x8d, 0x64, 0x8e, 0x58, 0xa0, 0x45, 0xaf, 0x98, 0xe1, 0x2b, 0x95, 0x44, 0x97, 0xa2, 0x31,
]);

pub(crate) trait CanonicalCommandIdentity {
    fn canonical_command_uuid(&self) -> Uuid;
}

impl CanonicalCommandIdentity for CommandId {
    fn canonical_command_uuid(&self) -> Uuid {
        *self.as_uuid()
    }
}

pub(crate) trait IntoCanonicalCommandId {
    fn into_canonical_command_id(self) -> CommandId;
}

impl IntoCanonicalCommandId for CommandId {
    fn into_canonical_command_id(self) -> CommandId {
        self
    }
}

#[cfg(test)]
impl CanonicalCommandIdentity for str {
    fn canonical_command_uuid(&self) -> Uuid {
        CommandId::parse(self)
            .expect("test command_id must be a canonical UUID")
            .canonical_command_uuid()
    }
}

#[cfg(test)]
impl IntoCanonicalCommandId for &str {
    fn into_canonical_command_id(self) -> CommandId {
        CommandId::parse(self).expect("test command_id must be a canonical UUID")
    }
}

#[cfg(test)]
impl IntoCanonicalCommandId for String {
    fn into_canonical_command_id(self) -> CommandId {
        CommandId::parse(&self).expect("test command_id must be a canonical UUID")
    }
}

pub(crate) fn user_message_id(
    _personality_agent_id: &PersonalityAgentId,
    command_id: &(impl CanonicalCommandIdentity + ?Sized),
) -> String {
    Uuid::new_v5(
        &crate::gateway::wire::USER_MESSAGE_ID_NAMESPACE,
        command_id.canonical_command_uuid().as_bytes(),
    )
    .to_string()
}

const TOOL_RESULT_MESSAGE_ID_NAMESPACE: Uuid = Uuid::from_bytes([
    0x73, 0x75, 0x6d, 0x69, 0xa4, 0xc1, 0x48, 0x22, 0x91, 0x5d, 0xb5, 0xd2, 0x5a, 0x69, 0x9f, 0x31,
]);

/// Stable transcript identity shared by the live run loop and cold-boot
/// logical recovery. Hashing each variable-length component independently
/// keeps the pair framing unambiguous.
pub(crate) fn tool_result_message_id(assistant_message_id: &str, tool_call_id: &str) -> String {
    let assistant_digest = Sha256::digest(assistant_message_id.as_bytes());
    let tool_call_digest = Sha256::digest(tool_call_id.as_bytes());
    let mut pair_digest = [0_u8; 64];
    pair_digest[..32].copy_from_slice(&assistant_digest);
    pair_digest[32..].copy_from_slice(&tool_call_digest);
    Uuid::new_v5(&TOOL_RESULT_MESSAGE_ID_NAMESPACE, &pair_digest).to_string()
}

impl InjectedCommand {
    #[allow(
        dead_code,
        reason = "the T15 run loop consumes the T12-frozen private injection builder"
    )]
    pub(crate) fn new(
        seq: u64,
        command_id: impl IntoCanonicalCommandId,
        provenance: DirectChatProvenanceV1,
    ) -> Self {
        let command_id = command_id.into_canonical_command_id();
        let message_id = user_message_id(provenance.personality_agent_id(), &command_id);
        Self {
            seq,
            command_id,
            message_id,
            provenance,
        }
    }

    #[cfg(test)]
    pub(crate) fn seq(&self) -> u64 {
        self.seq
    }

    #[cfg(test)]
    pub(crate) fn command_id(&self) -> &str {
        self.command_id.as_str()
    }

    #[cfg(test)]
    pub(crate) fn message_id(&self) -> &str {
        &self.message_id
    }

    pub(crate) const fn provenance(&self) -> &DirectChatProvenanceV1 {
        &self.provenance
    }

    #[cfg(test)]
    fn with_caller_message_id(
        seq: u64,
        command_id: CommandId,
        message_id: impl Into<String>,
        provenance: DirectChatProvenanceV1,
    ) -> Self {
        Self {
            seq,
            command_id,
            message_id: message_id.into(),
            provenance,
        }
    }
}

